enum AuthStep { case signIn, otp, success }

struct AuthSheet: View {
  @State private var step: AuthStep = .signIn
  @State private var number = ""
  @State private var code = ""

  var body: some View {
    NavigationStack {
      Group {
        switch step {
        case .signIn: SignInView(number: $number) { step = .otp }
        case .otp:    OTPView(code: $code) { step = .success }
        case .success: SuccessView()
        }
      }
      .animation(.spring(response: 0.46, dampingFraction: 0.86), value: step)
    }
    .presentationCornerRadius(38)
    .presentationDetents([.large])
  }
}

HStack(spacing: 10) {
  HStack(spacing: 10) {
    Text("+965").font(.custom("UrbaneRounded-Light", size: 22))
    Image(systemName: "chevron.down").font(.system(size: 14))
  }
  TextField("", text: $number)
    .keyboardType(.numberPad)
    .font(.custom("UrbaneRounded-Light", size: 22))
    .foregroundStyle(Color(hex: 0xED1C24))
    .onChange(of: number) { number = String($0.filter(\.isNumber).prefix(8)) }
}
.overlay(alignment: .bottom) {
  Rectangle().frame(height: 1)
    .foregroundStyle(showError ? Color(hex: 0xED1C24) : Color(hex: 0xE5E5E5))
}
// invalid submit: shake + UINotificationFeedbackGenerator().notificationOccurred(.error)

HStack(spacing: 18) {
  ForEach(0..<4) { i in
    ZStack {
      Circle().strokeBorder(borderColor(i), lineWidth: 2)
      Text(digit(i)).font(.custom("ProximaNova-Regular", size: 15))
    }
    .frame(width: 44, height: 44)
    .scaleEffect(verifying ? 1.07 : 1)
    .animation(verifying ? .easeInOut(duration: 0.35).repeatForever() : .default, value: verifying)
  }
}
func borderColor(_ i: Int) -> Color {
  if error { return Color(hex: 0xED1C24) }
  return i < code.count ? Color(hex: 0x454545) : Color(hex: 0xE5E5E5)
}

import LocalAuthentication

func signInWithFaceID() {
  let ctx = LAContext()
  guard ctx.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: nil) else { return }
  ctx.evaluatePolicy(.deviceOwnerAuthenticationWithBiometrics,
                     localizedReason: "Sign in to DietStation") { ok, _ in
    DispatchQueue.main.async {
      if ok {
        UINotificationFeedbackGenerator().notificationOccurred(.success)
        step = .success   // then dismiss back to home
      }
    }
  }
}

